ground_truth:
define-command -hidden -docstring "Show the current buffer name" mytool-status %{
    echo %val{bufname}
}

define-command -docstring "Move down one line" mytool-j %{
    execute-keys j
}

define-command -docstring "Move down and delete the selection" mytool-del %{
    execute-keys j
    evaluate-commands delete-anchored
}

define-command -docstring "Echo a literal percent-brace and quote" mytool-escape %{
    echo "%%{foo}'bar"
}

declare-option bool mytool_verbose false

define-command -docstring "Enable verbose mode" mytool-verbose-on %{
    evaluate-commands -no-hooks { set-option global mytool_verbose true }
}

define-command -docstring "Highlight TODO occurrences" mytool-highlight-todo %{
    add-highlighter --override mytool-todo regex TODO fg:red
}

define-command -docstring "Print the current directory" mytool-run %{
    %sh{
        printf '%s\n' "$PWD"
    }
}

